"""es-vi top-up batch 07 (QC 2026-10-29 evening §2): A1-2 stories that give the A1 syllabus
lexemes met only in A2-1 stories a level-correct context. Appended after batch 06, so the
reading order's head (and the band-1 audio list) is unchanged; none of these bundles audio."""
import importlib.util, os
spec = importlib.util.spec_from_file_location("lib", os.path.join(os.path.dirname(__file__), "es-stories-lib.py"))
lib = importlib.util.module_from_spec(spec); spec.loader.exec_module(lib)
story = lib.story

S = []
S.append(story("la_pelicula_del_domingo", "A1-2", "La película del domingo",
 ("Chủ nhật nào gia đình Ruiz cũng xem phim. Hôm nay bà Carmen chọn một phim hình sự, và bà đoán ra kẻ giết người trước cả ông trung sĩ.", "Every Sunday the Ruiz family watches a film. Today Grandma Carmen picks a crime film, and she guesses the killer before the sergeant does."),
 ["sargento", "pista", "averiguar"],
 [("N", "Todos los domingos, la familia Ruiz mira una película después de cenar.", "Chủ nhật nào gia đình Ruiz cũng xem một bộ phim sau bữa tối.", "Every Sunday, the Ruiz family watches a film after dinner."),
  ("N", "Hoy elige la abuela Carmen. Ella prefiere las películas de crimen.", "Hôm nay đến lượt bà Carmen chọn. Bà thích phim hình sự hơn cả.", "Today Grandma Carmen chooses. She prefers crime films."),
  ("N", "En la primera escena, una dama aparece muerta en su habitación.", "Trong cảnh đầu tiên, người ta thấy một quý bà đã chết trong phòng riêng.", "In the first scene, a lady is found dead in her room."),
  ("N", "Es un asesinato. La policía cree que alguien disparó desde la ventana.", "Đó là một vụ giết người. Cảnh sát cho rằng có kẻ đã bắn từ cửa sổ.", "It's a murder. The police think someone fired from the window."),
  ("N", "Un sargento llega a la casa con un oficial y dos agentes. Quiere averiguar qué sucede en esa familia.", "Một ông trung sĩ đến ngôi nhà cùng một sĩ quan và hai cảnh sát. Ông muốn tìm hiểu chuyện gì đang xảy ra trong gia đình đó.", "A sergeant arrives at the house with an officer and two policemen. He wants to find out what is going on in that family."),
  ("N", "El sargento mira a la dama muerta. Nadie sabe cómo murió: es un caso muy difícil.", "Ông trung sĩ nhìn quý bà đã chết. Không ai biết bà chết thế nào: đây là một vụ án rất khó.", "The sergeant looks at the dead lady. Nobody knows how she died: it's a very difficult case."),
  ("A", "¡Ese sargento es muy listo! Mirad sus ojos.", "Ông trung sĩ này thông minh lắm! Nhìn mắt ông ấy mà xem.", "That sergeant is very clever! Look at his eyes."),
  ("B", "Abuela, no hables tanto. Quiero oír las voces.", "Bà ơi, bà đừng nói nhiều thế. Cháu muốn nghe các nhân vật nói.", "Grandma, don't talk so much. I want to hear the voices."),
  ("N", "En la casa hay cuatro personas: el marido, la hija, un caballero joven y el guardia de la puerta.", "Trong nhà có bốn người: người chồng, cô con gái, một quý ông trẻ tuổi và người bảo vệ ở cửa.", "There are four people in the house: the husband, the daughter, a young gentleman and the guard at the door."),
  ("N", "El sargento pregunta a todos: «¿A qué hora ocurrió exactamente?».", "Ông trung sĩ hỏi mọi người: «Chính xác thì chuyện xảy ra lúc mấy giờ?».", "The sergeant asks everyone: \"At what time exactly did it happen?\""),
  ("N", "Primero habla con el marido. El hombre tiene una voz triste, pero la abuela no le cree.", "Trước tiên ông nói chuyện với người chồng. Người đàn ông có giọng buồn bã, nhưng bà không tin ông ta.", "First he talks to the husband. The man has a sad voice, but Grandma doesn't believe him."),
  ("A", "Ese hombre miente. Una persona triste no habla así.", "Lão ấy nói dối. Người buồn thật thì không nói như thế.", "That man is lying. A sad person doesn't talk like that."),
  ("B", "¿Cómo lo sabes? Simplemente no te gusta su cara.", "Sao bà biết ạ? Chỉ đơn giản là bà không thích mặt ông ta thôi.", "How do you know? You simply don't like his face."),
  ("N", "Después, el sargento descubre una pista: un papel con un número de teléfono debajo de la cama.", "Sau đó, ông trung sĩ phát hiện một manh mối: một mẩu giấy ghi số điện thoại dưới gầm giường.", "Then the sergeant discovers a clue: a piece of paper with a phone number under the bed."),
  ("N", "Uno de los agentes toca el papel con la mano.", "Một cảnh sát lấy tay chạm vào mẩu giấy.", "One of the officers touches the paper with his hand."),
  ("A", "¡Qué agente tan estúpido! Así no se trabaja.", "Cảnh sát gì mà ngốc thế! Làm việc như thế là hỏng.", "What a stupid officer! That's no way to work."),
  ("N", "Es el número de un abogado. La víctima quería dejar su dinero a otra persona: ¡un millón de dólares!", "Đó là số của một luật sư. Nạn nhân từng muốn để lại tiền cho một người khác: một triệu đô la!", "It's a lawyer's number. The victim wanted to leave her money to someone else: a million dollars!"),
  ("N", "Ahora todos tienen una razón para matar.", "Giờ thì ai cũng có lý do để giết người.", "Now everyone has a reason to kill."),
  ("B", "Pero ¿quién puede asesinar a su propia madre?", "Nhưng ai lại có thể giết chính mẹ mình chứ?", "But who could murder their own mother?"),
  ("B", "Probablemente es la hija. Mira, tiene miedo.", "Chắc là cô con gái. Bà nhìn kìa, cô ta đang sợ.", "It's probably the daughter. Look, she's scared."),
  ("A", "No. Usa el cerebro, Pablo. La hija no puede disparar: tiene el brazo roto.", "Không phải. Dùng cái đầu đi, Pablo. Cô con gái không thể bắn được: tay cô ấy đang bị gãy.", "No. Use your brain, Pablo. The daughter can't shoot: her arm is broken."),
  ("N", "El caballero joven estaba en un bar del centro a esa hora, pero no tiene testigos.", "Lúc đó quý ông trẻ đang ở một quán bar trong trung tâm, nhưng anh ta không có nhân chứng.", "The young gentleman was at a bar in the centre at that time, but he has no witnesses."),
  ("N", "Y el guardia no habla. Solo mira la ventana.", "Còn người bảo vệ thì không nói gì. Ông ta chỉ nhìn ra cửa sổ.", "And the guard doesn't speak. He just looks at the window."),
  ("A", "¡Es él! Ese hombre tiene una mente muy oscura. Lo sé.", "Chính hắn! Đầu óc gã đó đen tối lắm. Bà biết mà.", "It's him! That man has a very dark mind. I know it."),
  ("B", "¿El guardia? ¡Eso es increíble!", "Người bảo vệ á? Không thể tin được!", "The guard? That's incredible!"),
  ("N", "En la última escena, el guardia intenta escapar por la ventana.", "Trong cảnh cuối, người bảo vệ tìm cách trốn qua cửa sổ.", "In the last scene, the guard tries to escape through the window."),
  ("N", "Pero los agentes lo atrapan en la calle y el sargento lo detiene.", "Nhưng các cảnh sát tóm được hắn ngoài phố và ông trung sĩ bắt giữ hắn.", "But the officers catch him in the street and the sergeant arrests him."),
  ("N", "El guardia es realmente el hijo de la víctima, pero nadie lo sabía. Quería el dinero para él solo.", "Thật ra người bảo vệ là con trai của nạn nhân, nhưng không ai biết điều đó. Hắn muốn chỗ tiền cho riêng mình.", "The guard is really the victim's son, but nobody knew. He wanted the money all for himself."),
  ("B", "Abuela, ¿cómo lo sabías?", "Bà ơi, sao bà biết được ạ?", "Grandma, how did you know?"),
  ("A", "Es normal. En estas películas, el que menos habla es siempre el malo.", "Bình thường thôi. Trong mấy phim này, kẻ ít nói nhất bao giờ cũng là kẻ xấu.", "It's normal. In these films, the one who talks least is always the bad guy."),
  ("N", "Pablo se ríe. La próxima semana va a elegir él la película: una de amor.", "Pablo bật cười. Tuần sau cậu sẽ là người chọn phim: một phim tình cảm.", "Pablo laughs. Next week he's going to choose the film: a love story.")],
 [("locate", "Bà Carmen thích loại phim nào?", "What kind of films does Grandma Carmen prefer?", [("Phim tình cảm", "Love films"), ("Phim hình sự", "Crime films"), ("Phim hoạt hình", "Cartoons")], 1),
  ("locate", "Ông trung sĩ tìm thấy manh mối gì?", "What clue does the sergeant find?", [("Một mẩu giấy ghi số điện thoại dưới gầm giường", "A piece of paper with a phone number under the bed"), ("Một chiếc chìa khóa", "A key"), ("Một chiếc điện thoại", "A phone")], 0),
  ("infer", "Vì sao bà Carmen đoán ra kẻ giết người?", "Why does Grandma Carmen guess who the killer is?", [("Vì bà đã xem phim này rồi", "Because she has already seen this film"), ("Vì trong những phim như thế, kẻ ít nói nhất thường là thủ phạm", "Because in films like this the one who says least is usually the culprit"), ("Vì Pablo nói cho bà biết", "Because Pablo tells her")], 1)],
 names=["Ruiz", "Carmen", "Pablo"],
 token_map={"roto": "es:w:romper", "muerta": "es:w:muerto"}))

S.append(story("el_juicio_de_la_manzana", "A1-2", "El juicio de la manzana",
 ("Quả táo trên bàn cô giáo biến mất, và cả lớp nghi Hugo. Cô Marta cho cả lớp xử một phiên tòa giả để tìm ra sự thật.", "The apple on the teacher's desk has disappeared, and the class suspects Hugo. Marta, the teacher, lets the class hold a pretend trial to find out what happened."),
 ["juez", "testigo", "pena"],
 [("N", "Hoy, en la escuela, la profesora Marta tiene una idea para la clase.", "Hôm nay ở trường, cô giáo Marta có một ý tưởng cho cả lớp.", "Today at school, Marta the teacher has an idea for the class."),
  ("N", "Ayer desapareció la manzana roja de su mesa. Todos culpan a Hugo, porque estaba solo en la clase a las doce.", "Hôm qua quả táo đỏ trên bàn cô biến mất. Mọi người đều đổ lỗi cho Hugo, vì lúc mười hai giờ cậu ở một mình trong lớp.", "Yesterday the red apple on her desk disappeared. Everyone blames Hugo, because he was alone in the classroom at twelve."),
  ("A", "Vamos a hacer un juicio, pero solo es un juego. Yo no voy a hablar: este asunto es de la clase.", "Chúng ta sẽ làm một phiên tòa, nhưng chỉ là trò chơi thôi. Cô sẽ không nói gì: chuyện này là của cả lớp.", "We're going to hold a trial, but it's only a game. I'm not going to speak: this matter belongs to the class."),
  ("A", "Sofía, tú eres la juez. Tienes que mantener el orden: no permites hablar a todos a la vez.", "Sofía, em làm thẩm phán. Em phải giữ trật tự: không cho mọi người nói cùng một lúc.", "Sofía, you're the judge. You have to keep order: you don't let everyone talk at once."),
  ("A", "Lucas es el abogado de Hugo, y Nuria es la abogada de la clase.", "Lucas là luật sư của Hugo, còn Nuria là luật sư của cả lớp.", "Lucas is Hugo's lawyer, and Nuria is the class's lawyer."),
  ("N", "Sofía se sienta a la mesa de la profesora y golpea la mesa con un libro.", "Sofía ngồi vào bàn cô giáo và lấy cuốn sách gõ xuống bàn.", "Sofía sits at the teacher's desk and bangs on it with a book."),
  ("A", "¡Atención! Comienza el juicio. Hugo, ¿quieres responder a la clase?", "Mọi người chú ý! Phiên tòa bắt đầu. Hugo, em có muốn trả lời cả lớp không?", "Attention! The trial begins. Hugo, do you want to answer the class?"),
  ("B", "Sí. No sé a qué manzana se refieren.", "Có ạ. Tớ không biết các bạn đang nói đến quả táo nào.", "Yes. I don't know which apple they mean."),
  ("A", "Señora juez, Hugo tiene la culpa. Es la única persona que estaba en la clase.", "Thưa quý tòa, Hugo có lỗi. Bạn ấy là người duy nhất ở trong lớp.", "Your Honour, Hugo is to blame. He's the only person who was in the classroom."),
  ("A", "Y tengo una prueba: Hugo siempre come fruta a las doce.", "Và tôi có một bằng chứng: lúc mười hai giờ Hugo lúc nào cũng ăn trái cây.", "And I have a piece of evidence: Hugo always eats fruit at twelve."),
  ("B", "Eso no es una prueba suficiente. Muchos niños comen fruta.", "Như thế chưa đủ làm bằng chứng. Nhiều bạn ăn trái cây mà.", "That's not enough evidence. Lots of children eat fruit."),
  ("B", "Hugo, no te preocupes. Imagina que estás en casa.", "Hugo, cậu đừng lo. Cứ tưởng tượng là cậu đang ở nhà.", "Hugo, don't worry. Imagine you're at home."),
  ("N", "Hugo trata de no reír, pero es bastante difícil.", "Hugo cố nhịn cười, nhưng khá là khó.", "Hugo tries not to laugh, but it's quite difficult."),
  ("A", "¿Hay testigos?", "Có nhân chứng nào không?", "Are there any witnesses?"),
  ("N", "Ana levanta la mano. Ella es testigo.", "Ana giơ tay. Cô bé là nhân chứng.", "Ana raises her hand. She is a witness."),
  ("A", "Yo vi a Hugo con algo rojo en la mano.", "Tớ thấy Hugo cầm một thứ màu đỏ trong tay.", "I saw Hugo with something red in his hand."),
  ("B", "¡Sí, pero era mi móvil! Es rojo, miren.", "Đúng, nhưng đó là điện thoại của tớ! Nó màu đỏ, mọi người xem này.", "Yes, but it was my phone! It's red, look."),
  ("N", "Hugo muestra su móvil rojo a toda la clase. Todos se ríen.", "Hugo đưa chiếc điện thoại màu đỏ cho cả lớp xem. Ai cũng bật cười.", "Hugo shows his red phone to the whole class. Everyone laughs."),
  ("B", "¿Ven? Es posible que Ana se equivoque. Supongo que no vio bien.", "Thấy chưa? Có thể Ana đã nhầm. Tôi cho rằng bạn ấy nhìn không rõ.", "See? Ana may be mistaken. I suppose she didn't see properly."),
  ("A", "Pero, señora juez, ¿podemos confiar en Hugo? Siempre hace bromas.", "Nhưng thưa quý tòa, chúng ta có tin Hugo được không? Bạn ấy lúc nào cũng đùa.", "But, Your Honour, can we trust Hugo? He's always playing jokes."),
  ("B", "Hago bromas, sí, pero no miento. ¡No me importa la manzana! No me gustan las manzanas.", "Tớ hay đùa, đúng, nhưng tớ không nói dối. Tớ chẳng quan tâm quả táo! Tớ không thích táo.", "I play jokes, yes, but I don't lie. I don't care about the apple! I don't like apples."),
  ("N", "La juez tiene que tomar una decisión.", "Thẩm phán phải đưa ra quyết định.", "The judge has to make a decision."),
  ("A", "No hay pruebas. Según la ley de esta clase, Hugo es libre. Ordeno soltar a Hugo.", "Không có bằng chứng. Theo luật của lớp này, Hugo được tự do. Tôi ra lệnh thả Hugo.", "There's no evidence. According to the law of this class, Hugo is free. I order Hugo to be released."),
  ("B", "¡Gracias! Ahora podemos liberar a mi cliente.", "Cảm ơn quý tòa! Giờ thì thân chủ của tôi được thả rồi.", "Thank you! Now we can free my client."),
  ("N", "En ese momento, se abre la puerta y entra el señor Gil, el profesor de música.", "Đúng lúc đó, cửa mở và thầy Gil, giáo viên âm nhạc, bước vào.", "At that moment, the door opens and Mr Gil, the music teacher, comes in."),
  ("B", "Perdón, Marta. Ayer me llevé tu manzana. Tenía mucha hambre. ¡Disculpa!", "Xin lỗi chị Marta. Hôm qua tôi đã lấy quả táo của chị. Tôi đói quá. Thứ lỗi cho tôi nhé!", "Sorry, Marta. Yesterday I took your apple. I was very hungry. Forgive me!"),
  ("N", "Toda la clase dice a la vez: «¡A la cárcel! ¡A la prisión!».", "Cả lớp đồng thanh: «Bỏ tù! Cho vào tù!».", "The whole class says at once: \"To jail! To prison!\""),
  ("A", "Bueno, acepto. Pero la pena es esta: mañana traes fruta para toda la clase.", "Thôi được, tôi chấp nhận. Nhưng hình phạt là thế này: ngày mai anh mang trái cây cho cả lớp.", "All right, I accept. But the punishment is this: tomorrow you bring fruit for the whole class."),
  ("N", "El señor Gil no puede decir que no. Y Hugo está feliz: ya no teme a nadie.", "Thầy Gil không thể từ chối. Còn Hugo thì vui lắm: giờ cậu chẳng còn sợ ai nữa.", "Mr Gil can't say no. And Hugo is happy: now he isn't afraid of anyone.")],
 [("locate", "Cái gì đã biến mất?", "What has disappeared?", [("Điện thoại của Hugo", "Hugo's phone"), ("Quả táo đỏ trên bàn cô giáo", "The red apple on the teacher's desk"), ("Cuốn sách của Sofía", "Sofía's book")], 1),
  ("locate", "Thứ màu đỏ Ana nhìn thấy trong tay Hugo là gì?", "What was the red thing Ana saw in Hugo's hand?", [("Quả táo", "The apple"), ("Một cuốn sách", "A book"), ("Điện thoại của Hugo", "Hugo's phone")], 2),
  ("infer", "Vì sao cuối cùng thầy Gil phải mang trái cây cho cả lớp?", "Why does Mr Gil have to bring fruit for the class in the end?", [("Vì chính thầy đã lấy quả táo", "Because he was the one who took the apple"), ("Vì thầy là thẩm phán", "Because he is the judge"), ("Vì hôm đó là sinh nhật thầy", "Because it's his birthday")], 0)],
 names=["Marta", "Hugo", "Sofía", "Lucas", "Nuria", "Ana", "Gil"]))

S.append(story("la_mision_de_leo", "A1-2", "La misión de Leo",
 ("Leo rủ chị gái Clara chơi một trò chơi trên máy tính: phải cứu Trái Đất khỏi một đội quân quỷ. Clara vốn ghét trò chơi điện tử.", "Leo asks his sister Clara to play a computer game: they must save the Earth from an army of demons. Clara has always hated video games."),
 ["nave", "demonio", "ejército"],
 [("N", "Leo y su hermana Clara son hermanos, pero casi nunca juegan juntos.", "Leo và chị gái Clara là chị em ruột, nhưng hầu như chẳng bao giờ chơi cùng nhau.", "Leo and his sister Clara are siblings, but they almost never play together."),
  ("N", "Leo tiene diez años y Clara tiene quince. Ella prefiere los libros.", "Leo mười tuổi, còn Clara mười lăm. Chị thích đọc sách hơn.", "Leo is ten and Clara is fifteen. She prefers books."),
  ("N", "Un sábado por la tarde, Leo le pide ayuda con un juego nuevo en el ordenador.", "Một chiều thứ Bảy, Leo nhờ chị giúp chơi một trò chơi mới trên máy tính.", "One Saturday afternoon, Leo asks her for help with a new game on the computer."),
  ("B", "Es un juego del futuro. Tenemos una misión: salvar la Tierra.", "Đây là trò chơi về tương lai. Chúng mình có một nhiệm vụ: cứu Trái Đất.", "It's a game set in the future. We have a mission: to save the Earth."),
  ("A", "¿Salvar la Tierra? ¿De qué?", "Cứu Trái Đất? Khỏi cái gì cơ?", "Save the Earth? From what?"),
  ("B", "De un ejército de demonios de otro mundo. Quieren empezar una guerra.", "Khỏi một đội quân quỷ từ thế giới khác. Chúng muốn gây chiến tranh.", "From an army of demons from another world. They want to start a war."),
  ("A", "Vale. Pero yo soy la capitana de la nave.", "Được thôi. Nhưng chị làm thuyền trưởng con tàu.", "OK. But I'm the captain of the ship."),
  ("B", "No, tú eres el general. Es más importante.", "Không, chị làm đại tướng. Quan trọng hơn mà.", "No, you're the general. It's more important."),
  ("N", "Primero tienen que crear su equipo. Cada miembro tiene una fuerza diferente.", "Trước tiên họ phải lập đội của mình. Mỗi thành viên có một sức mạnh khác nhau.", "First they have to create their team. Each member has a different strength."),
  ("N", "Leo decide formar un grupo de cuatro muchachos muy fuertes. Clara elige a una mujer que puede volar.", "Leo quyết định lập một nhóm gồm bốn chàng trai rất khỏe. Clara thì chọn một cô gái biết bay.", "Leo decides to form a group of four very strong young men. Clara chooses a woman who can fly."),
  ("N", "Después, tienen que armar la nave con energía y con un sistema de seguridad muy bueno.", "Sau đó, họ phải trang bị cho con tàu năng lượng và một hệ thống an ninh thật tốt.", "Then they have to equip the ship with energy and a very good security system."),
  ("B", "La nave tiene que partir ya. Tú tienes el control, y yo voy a lanzar los ataques.", "Con tàu phải xuất phát ngay. Chị điều khiển, còn em sẽ tung các đòn tấn công.", "The ship has to leave now. You've got the controls, and I'm going to launch the attacks."),
  ("N", "En el primer nivel, los demonios atacan la nave, y la nave se mueve mucho.", "Ở màn đầu tiên, lũ quỷ tấn công, và con tàu chao đảo dữ dội.", "In the first level, the demons attack, and the ship moves a lot."),
  ("A", "¡Tenemos que proteger la nave! ¿Qué tengo que usar?", "Phải bảo vệ con tàu! Chị phải dùng cái gì đây?", "We have to protect the ship! What do I have to use?"),
  ("B", "Toca la luz roja. Y salta cuando suena la música.", "Chạm vào đèn đỏ ấy. Và nhảy lên khi nhạc vang lên.", "Touch the red light. And jump when the music plays."),
  ("N", "Clara aprende rápido. Cada movimiento es perfecto.", "Clara học rất nhanh. Mỗi động tác của chị đều hoàn hảo.", "Clara learns fast. Every move is perfect."),
  ("B", "¡Qué valor tienes, Clara!", "Chị gan dạ thật đấy, chị Clara!", "You're so brave, Clara!"),
  ("N", "Los dos luchan juntos y pelean contra cien demonios.", "Hai chị em cùng nhau chiến đấu và đánh lại một trăm con quỷ.", "The two of them fight together, battling a hundred demons."),
  ("N", "Con un último golpe, Leo logra quitar la energía al jefe de los demonios.", "Bằng đòn cuối cùng, Leo lấy được hết năng lượng của tên trùm quỷ.", "With one last blow, Leo manages to take the energy away from the demon chief."),
  ("N", "El jefe se convierte en una pequeña luz y desaparece. ¡Ganan la operación!", "Tên trùm biến thành một đốm sáng nhỏ rồi biến mất. Họ thắng trận!", "The chief turns into a small light and disappears. They win the operation!"),
  ("N", "Entonces Clara mira la hora. El ordenador marca las diez de la noche.", "Lúc ấy Clara nhìn đồng hồ. Máy tính hiện mười giờ tối.", "Then Clara looks at the time. The computer shows ten at night."),
  ("A", "¡Dios mío! Estamos aquí desde las seis.", "Trời ơi! Chúng mình ngồi đây từ sáu giờ.", "My God! We've been here since six."),
  ("B", "¿Ves? Unimos fuerzas y salvamos el mundo.", "Thấy chưa? Chúng mình hợp sức và đã cứu thế giới.", "See? We joined forces and saved the world."),
  ("A", "El sábado pasado yo odiaba estos juegos. Ahora quiero jugar contigo otra vez.", "Thứ Bảy tuần trước chị còn ghét mấy trò này. Giờ chị muốn chơi với em lần nữa.", "Last Saturday I hated these games. Now I want to play with you again."),
  ("B", "Mañana, el segundo nivel. Pero primero, la paz: ¡vamos a cenar!", "Mai chơi màn hai nhé. Nhưng giờ thì hòa bình đã: đi ăn tối thôi!", "Tomorrow, level two. But first, peace: let's have dinner!")],
 [("locate", "Nhiệm vụ trong trò chơi là gì?", "What is the mission in the game?", [("Cứu Trái Đất", "To save the Earth"), ("Tìm một kho báu", "To find a treasure"), ("Đến một hòn đảo", "To reach an island")], 0),
  ("locate", "Clara chọn thành viên nào cho đội?", "Which team member does Clara choose?", [("Bốn chàng trai khỏe mạnh", "Four strong young men"), ("Một cô gái biết bay", "A woman who can fly"), ("Một con chó", "A dog")], 1),
  ("infer", "Cuối truyện, Clara thay đổi thế nào?", "How has Clara changed by the end of the story?", [("Chị vẫn ghét trò chơi điện tử", "She still hates video games"), ("Chị muốn đi ngủ sớm", "She wants to go to bed early"), ("Chị đã thích chơi cùng em trai", "She now likes playing with her brother")], 2)],
 names=["Leo", "Clara"],
 token_map={"capitana": "es:w:capitan", "ayuda": "es:w:ayuda", "ataques": "es:w:ataque"}))

S.append(story("la_carrera_de_rosa", "A1-2", "La carrera de Rosa",
 ("Bà Rosa 70 tuổi muốn chạy một cuộc đua trong thành phố. Bạn trai của bà, ông Tomás, nghĩ bà bị điên.", "Rosa is 70 and wants to run in a race in her town. Her boyfriend, Tomás, thinks she's crazy."),
 ["carrera", "piel", "oído"],
 [("N", "Rosa tiene 70 años y un corazón muy fuerte.", "Bà Rosa 70 tuổi và có một trái tim rất khỏe.", "Rosa is 70 and has a very strong heart."),
  ("N", "Todas las mañanas camina una hora por la playa con su novio, Tomás.", "Sáng nào bà cũng đi bộ một tiếng dọc bãi biển cùng bạn trai là ông Tomás.", "Every morning she walks for an hour along the beach with her boyfriend, Tomás."),
  ("N", "Un día, Rosa lee en el móvil que hay una carrera en su ciudad.", "Một hôm, bà Rosa đọc trên điện thoại rằng thành phố của bà sắp có một cuộc chạy đua.", "One day, Rosa reads on her phone that there's a race in her town."),
  ("A", "Tomás, quiero correr en esa carrera. ¿Corres conmigo?", "Tomás à, em muốn chạy cuộc đua đó. Anh chạy cùng em không?", "Tomás, I want to run in that race. Will you run with me?"),
  ("B", "¿Estás loca? Eres maravillosa, pero tienes 70 años.", "Em điên à? Em tuyệt vời thật, nhưng em 70 tuổi rồi.", "Are you crazy? You're wonderful, but you're 70."),
  ("A", "¿Y qué? Mi cuerpo todavía funciona muy bien.", "Thì sao? Cơ thể em vẫn còn hoạt động tốt lắm.", "So what? My body still works very well."),
  ("N", "Primero, Rosa va al doctor. El doctor escucha su corazón y mira su piel, su boca y sus oídos.", "Trước tiên, bà Rosa đi khám. Bác sĩ nghe tim, xem da, miệng và tai của bà.", "First, Rosa goes to the doctor. The doctor listens to her heart and looks at her skin, her mouth and her ears."),
  ("B", "Señora, todo está bien. Puede correr, pero no debe correr demasiado rápido.", "Thưa bà, mọi thứ đều ổn. Bà chạy được, nhưng không nên chạy nhanh quá.", "Madam, everything is fine. You can run, but you mustn't run too fast."),
  ("A", "¿Y el dolor de mi brazo?", "Thế còn cơn đau ở cánh tay tôi?", "And the pain in my arm?"),
  ("B", "No es nada. Quizá es porque usted levanta demasiadas cajas.", "Không sao đâu. Có lẽ là do bà nhấc quá nhiều thùng.", "It's nothing. Maybe it's because you lift too many boxes."),
  ("N", "Durante tres meses, Rosa y Tomás corren cada día por la playa.", "Suốt ba tháng, bà Rosa và ông Tomás ngày nào cũng chạy trên bãi biển.", "For three months, Rosa and Tomás run along the beach every day."),
  ("N", "Los primeros días, Tomás odia correr. Pero continúa por Rosa.", "Những ngày đầu, ông Tomás ghét chạy bộ. Nhưng ông vẫn tiếp tục vì bà Rosa.", "In the first days, Tomás hates running. But he carries on for Rosa."),
  ("N", "El día de la carrera hace mucho sol. Rosa se cubre los brazos y la cabeza, y lleva sus propios zapatos, los de siempre.", "Ngày đua trời nắng gắt. Bà Rosa che kín tay và đầu, và đi đôi giày quen thuộc của chính mình.", "On race day it's very sunny. Rosa covers her arms and head, and wears her own shoes, the usual ones."),
  ("N", "Allá, en la salida, hay muchos jóvenes. Algunos miran a Rosa y se ríen.", "Đằng kia, ở vạch xuất phát, có rất nhiều người trẻ. Vài người nhìn bà Rosa rồi cười.", "Over there, at the start, there are lots of young people. Some look at Rosa and laugh."),
  ("B", "¡Pobre señora! No va a llegar.", "Tội nghiệp bà cụ! Bà ấy không về đích được đâu.", "Poor lady! She's not going to make it."),
  ("N", "Pero a Rosa no la asusta nada.", "Nhưng chẳng gì làm bà Rosa sợ.", "But nothing scares Rosa."),
  ("A", "Ya veremos, muchacho.", "Rồi xem, chàng trai ạ.", "We'll see, young man."),
  ("N", "Comienza la carrera. Rosa no corre rápido, pero sigue y sigue. Dentro de su cabeza solo hay una idea: llegar.", "Cuộc đua bắt đầu. Bà Rosa chạy không nhanh, nhưng cứ chạy mãi. Trong đầu bà chỉ có một ý nghĩ: về đích.", "The race begins. Rosa doesn't run fast, but she keeps going. Inside her head there's only one idea: to finish."),
  ("N", "Muchos jóvenes corren demasiado rápido y luego ya no pueden más.", "Nhiều người trẻ chạy quá nhanh, rồi sau đó không chạy nổi nữa.", "Many young people run too fast and then can't go on."),
  ("N", "Incluso el muchacho de la salida está sentado en la calle, muy cansado.", "Ngay cả chàng trai ở vạch xuất phát cũng đang ngồi bệt bên đường, mệt lử.", "Even the young man from the start is sitting in the street, very tired."),
  ("N", "Ya falta poco. El corazón de Rosa va muy rápido, y Tomás la espera allí con agua.", "Sắp tới đích rồi. Tim bà Rosa đập rất nhanh, và ông Tomás đang chờ bà ở đó với nước.", "It's not far now. Rosa's heart is beating very fast, and Tomás is waiting for her there with water."),
  ("N", "Rosa no gana, pero tampoco pierde: llega antes que muchos jóvenes.", "Bà Rosa không thắng, nhưng cũng chẳng thua: bà về đích trước nhiều người trẻ.", "Rosa doesn't win, but she doesn't lose either: she finishes ahead of many young people."),
  ("N", "Tomás la besa con mucho cariño.", "Ông Tomás hôn bà đầy trìu mến.", "Tomás kisses her with great affection."),
  ("B", "Eres la mujer más hermosa de la carrera.", "Em là người phụ nữ đẹp nhất cuộc đua.", "You're the most beautiful woman in the race."),
  ("A", "¡Aún no lo creo! El año próximo corres tú conmigo.", "Em vẫn chưa tin nổi! Năm sau anh chạy cùng em nhé.", "I still can't believe it! Next year you run with me."),
  ("N", "Desde ese día, correr resulta muy bueno para los dos.", "Từ hôm đó, chạy bộ hóa ra rất tốt cho cả hai người.", "From that day on, running turns out to be very good for both of them.")],
 [("locate", "Bà Rosa đọc tin về cuộc đua ở đâu?", "Where does Rosa read about the race?", [("Trên điện thoại", "On her phone"), ("Trong một cuốn sách", "In a book"), ("Ở bãi biển", "At the beach")], 0),
  ("locate", "Bác sĩ khuyên bà Rosa điều gì?", "What does the doctor advise Rosa?", [("Không được chạy", "Not to run"), ("Không nên chạy nhanh quá", "Not to run too fast"), ("Chạy một mình", "To run alone")], 1),
  ("infer", "Vì sao chàng trai ở vạch xuất phát đã nhầm về bà Rosa?", "Why was the young man at the start wrong about Rosa?", [("Vì bà Rosa thắng cuộc đua", "Because Rosa won the race"), ("Vì bà Rosa không chạy", "Because Rosa didn't run"), ("Vì bà về đích còn anh ta thì không chạy nổi nữa", "Because she finished while he couldn't go on")], 2)],
 names=["Rosa", "Tomás"],
 token_map={"oídos": "es:w:oido"}))

S.append(story("el_bar_de_lucia", "A1-2", "El bar de Lucía",
 ("Lucía mất việc ở văn phòng. Anh bạn đồng nghiệp Andrés rủ cô mở một quán bar nhỏ gần nhà ga.", "Lucía loses her office job. Her colleague Andrés suggests they open a small bar near the station."),
 ["colega", "negocio", "cargo"],
 [("N", "Lucía trabaja en una oficina desde hace diez años. Suele llegar a las ocho y salir a las seis.", "Lucía làm việc ở một văn phòng đã mười năm. Cô thường đến lúc tám giờ và về lúc sáu giờ.", "Lucía has worked in an office for ten years. She usually arrives at eight and leaves at six."),
  ("N", "Un día, su jefe le dice que el negocio va mal y que ya no la necesitan.", "Một hôm, sếp bảo cô rằng công việc làm ăn đang tệ và họ không cần cô nữa.", "One day, her boss tells her that business is bad and they don't need her any more."),
  ("N", "Esa noche, Lucía llama a su colega Andrés.", "Tối hôm đó, Lucía gọi cho anh bạn đồng nghiệp Andrés.", "That night, Lucía calls her colleague Andrés."),
  ("B", "Lucía, esto puede ser una oportunidad. ¿Por qué no abrimos un bar?", "Lucía à, đây có thể là một cơ hội. Sao chúng mình không mở một quán bar?", "Lucía, this could be an opportunity. Why don't we open a bar?"),
  ("A", "¿Un bar? ¡No sé nada de bares!", "Một quán bar á? Mình chẳng biết gì về quán bar cả!", "A bar? I don't know anything about bars!"),
  ("B", "Yo sí. Mi padre tenía un bar, y tengo un plan.", "Mình thì biết. Bố mình từng có một quán, và mình có kế hoạch rồi.", "I do. My father had a bar, and I've got a plan."),
  ("N", "El plan es este: un bar pequeño, con café, sopa y un servicio muy rápido.", "Kế hoạch là thế này: một quán nhỏ, có cà phê, súp và phục vụ thật nhanh.", "The plan is this: a small bar, with coffee, soup and very fast service."),
  ("N", "Primero tienen que encontrar un lugar. Andrés busca en el móvil y encuentra uno cerca de la estación.", "Trước tiên họ phải tìm một địa điểm. Andrés tìm trên điện thoại và thấy một chỗ gần nhà ga.", "First they have to find a place. Andrés searches on his phone and finds one near the station."),
  ("N", "Lucía manda un correo para contactar con el señor Vidal, el hombre que vende el lugar.", "Lucía gửi một email để liên hệ với ông Vidal, người bán chỗ đó.", "Lucía sends an email to contact Mr Vidal, the man who is selling the place."),
  ("N", "Al día siguiente recibe la respuesta: el precio es bueno.", "Hôm sau cô nhận được trả lời: giá cả hợp lý.", "The next day she gets the answer: the price is good."),
  ("N", "Pero el lugar necesita mucho trabajo. Los dos limpian todo durante una semana.", "Nhưng chỗ này cần sửa sang nhiều. Hai người dọn dẹp mọi thứ suốt một tuần.", "But the place needs a lot of work. The two of them clean everything for a week."),
  ("N", "También tienen que decidir los cargos: Andrés está a cargo del café, y Lucía de las cuentas.", "Họ cũng phải chia việc: Andrés phụ trách cà phê, còn Lucía lo sổ sách.", "They also have to decide who does what: Andrés is in charge of the coffee, and Lucía of the accounts."),
  ("N", "Lucía guarda el dinero en una caja y escribe la dirección del bar en muchos papeles para las tiendas de la calle.", "Lucía cất tiền vào một chiếc hộp và viết địa chỉ quán lên nhiều tờ giấy để dán ở các cửa hàng trên phố.", "Lucía keeps the money in a box and writes the bar's address on lots of sheets of paper for the shops in the street."),
  ("N", "El primer día, Lucía se viste de negro, como los camareros de los hoteles.", "Ngày đầu tiên, Lucía mặc đồ đen, giống những người phục vụ ở khách sạn.", "On the first day, Lucía dresses in black, like the waiters in hotels."),
  ("N", "Pero no llega nadie. La espera es muy larga.", "Nhưng chẳng có ai đến. Chờ đợi mãi.", "But nobody comes. The wait is very long."),
  ("A", "¿Lo ves? Fue un error.", "Thấy chưa? Đúng là một sai lầm.", "See? It was a mistake."),
  ("B", "No te preocupes. Tengo otra idea, una forma de traer gente: música.", "Đừng lo. Mình có ý khác, một cách để kéo khách đến: âm nhạc.", "Don't worry. I have another idea, a way to bring people in: music."),
  ("N", "El hermano de Andrés toca en una banda, y la banda acepta tocar en el bar los jueves.", "Anh trai của Andrés chơi trong một ban nhạc, và ban nhạc đồng ý biểu diễn ở quán vào các tối thứ Năm.", "Andrés's brother plays in a band, and the band agrees to play in the bar on Thursdays."),
  ("A", "¿Qué tipo de música toca?", "Ban nhạc chơi loại nhạc gì?", "What kind of music do they play?"),
  ("B", "Música para bailar. Ya verás.", "Nhạc để nhảy. Rồi cậu xem.", "Music to dance to. You'll see."),
  ("N", "El jueves, el bar tiene muchos clientes. La gente baila y pide café y sopa.", "Tối thứ Năm, quán đông khách. Mọi người nhảy múa và gọi cà phê với súp.", "On Thursday, the bar has lots of customers. People dance and order coffee and soup."),
  ("N", "Lucía sirve las mesas muy rápido, y a las once un señor se acerca a ella. Su habla es de otro país, quizá de Argentina.", "Lucía phục vụ các bàn rất nhanh, và lúc mười một giờ có một ông khách đến gần cô. Giọng nói của ông là của một nước khác, có lẽ là Argentina.", "Lucía serves the tables very fast, and at eleven a man comes up to her. His way of speaking is from another country, maybe Argentina."),
  ("B", "Trabajo en un hotel cerca de aquí. Me gusta su manera de trabajar. ¿Pueden preparar café para nuestros clientes cada mañana?", "Tôi làm ở một khách sạn gần đây. Tôi thích cách làm việc của cô. Quán có thể pha cà phê cho khách của chúng tôi mỗi sáng không?", "I work at a hotel near here. I like your way of working. Could you make coffee for our guests every morning?"),
  ("A", "¡Claro que sí!", "Tất nhiên rồi!", "Of course!"),
  ("N", "Así comienza una buena relación entre el bar y el hotel. De este modo, el bar obtiene clientes todas las mañanas.", "Thế là bắt đầu mối quan hệ tốt đẹp giữa quán và khách sạn. Bằng cách đó, sáng nào quán cũng có khách.", "That's how a good relationship between the bar and the hotel begins. In this way, the bar gets customers every morning."),
  ("N", "Ahora Lucía actúa como una jefa, y no le molesta trabajar mucho.", "Giờ Lucía làm việc như một bà chủ thực thụ, và cô chẳng ngại làm nhiều.", "Now Lucía acts like a boss, and she doesn't mind working hard."),
  ("B", "¿Ves? Le debemos todo a tu jefe de la oficina.", "Thấy chưa? Chúng mình nợ ông sếp cũ của cậu tất cả đấy.", "See? We owe it all to your boss at the office.")],
 [("locate", "Quán bar mới ở gần đâu?", "Where is the new bar?", [("Gần bãi biển", "Near the beach"), ("Gần nhà ga", "Near the station"), ("Gần văn phòng cũ của Lucía", "Near Lucía's old office")], 1),
  ("locate", "Ý tưởng thứ hai của Andrés để kéo khách là gì?", "What is Andrés's second idea to bring customers in?", [("Âm nhạc", "Music"), ("Bán rẻ hơn", "Lower prices"), ("Mở cửa cả đêm", "Opening all night")], 0),
  ("infer", "Vì sao cuối truyện Andrés nói họ nợ ông sếp cũ của Lucía tất cả?", "Why does Andrés say at the end that they owe everything to Lucía's old boss?", [("Vì ông ấy cho họ tiền", "Because he gave them money"), ("Vì ông ấy là khách quen", "Because he is a regular customer"), ("Vì nếu Lucía không mất việc, họ đã không mở quán", "Because if Lucía hadn't lost her job, they wouldn't have opened the bar")], 2)],
 names=["Lucía", "Andrés", "Vidal", "Argentina"],
 token_map={"viste": "es:w:vestir", "habla": "es:w:habla", "cuentas": "es:w:cuenta"}))

lib.write_batch("07", S)
